import React, { useState } from 'react';

import AdminNavbar from './AdminNavbar';
import AdminSidebar from './AdminSidebar';
import AdminFooter from './AdminFooter';

const AdminLayout = ({ children }) => {
  // ==========================================
  // MOBILE SIDEBAR STATE
  // ==========================================
  const [sidebarOpen, setSidebarOpen] = useState(false);

  // ==========================================
  // OPEN SIDEBAR
  // ==========================================
  const openSidebar = () => {
    setSidebarOpen(true);
  };

  // ==========================================
  // CLOSE SIDEBAR
  // ==========================================
  const closeSidebar = () => {
    setSidebarOpen(false);
  };

  return (
    <div className="min-h-screen bg-gray-50">

      {/* ========================================
          SIDEBAR
      ======================================== */}
      <AdminSidebar
        isOpen={sidebarOpen}
        onClose={closeSidebar}
      />

      {/* ========================================
          NAVBAR
      ======================================== */}
      <AdminNavbar
        onMenuClick={openSidebar}
      />

      {/* ========================================
          MAIN AREA
      ======================================== */}
      <div
        className="
          min-h-screen
          pt-[72px]
          lg:ml-[250px]
          flex
          flex-col
        "
      >

        {/* ======================================
            PAGE CONTENT
        ====================================== */}
        <main
          className="
            flex-1
            bg-gray-50
          "
        >
          <div
            className="
              w-full
              max-w-[1600px]
              mx-auto

              px-4
              py-5

              sm:px-5
              sm:py-6

              lg:px-6
              lg:py-6

              xl:px-8
            "
          >
            {children}
          </div>
        </main>

        {/* ======================================
            FOOTER
        ====================================== */}
        <AdminFooter />

      </div>

    </div>
  );
};

export default AdminLayout;
